ALTER TABLE customers ADD COLUMN IF NOT EXISTS checkout_pending boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS customer_account_setup_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES customers(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_email_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE,customer_id uuid REFERENCES customers(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN ('receipt','welcome')),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','sent','failed','unknown','skipped')),attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),next_attempt_at timestamptz NOT NULL DEFAULT now(),attempted_at timestamptz,finished_at timestamptz,result text,UNIQUE(order_id,kind));
CREATE INDEX IF NOT EXISTS order_email_pending ON order_email_outbox(next_attempt_at,created_at) WHERE status='pending';
